<section class="page-head"><div><p class="muted">Administra las áreas que participan en el presupuesto municipal.</p></div><div class="page-actions"><input id="departmentSearch" class="search-input" placeholder="Buscar departamento..."><button class="btn btn-primary" id="newDepartmentBtn">+ Departamento</button></div></section><div id="departmentGrid" class="department-grid"></div>
<div class="modal hidden" id="departmentModal"><div class="modal-card"><div class="modal-head"><div><span class="eyebrow">ADMINISTRACIÓN</span><h2 id="departmentModalTitle">Nuevo departamento</h2></div><button class="icon-btn" data-close-modal>✕</button></div><form id="departmentForm" class="form-grid"><input type="hidden" name="departamento_id"><label>Código<input name="codigo" maxlength="30" placeholder="CUL" required></label><label>Nombre<input name="nombre" maxlength="150" placeholder="Cultura" required></label><label class="full">Descripción<textarea name="descripcion" rows="3"></textarea></label><label>Color institucional<input name="color_hex" type="color" value="#859F8E"></label><label>Icono<input name="icono" value="building"></label><label class="check-row full"><input name="es_tesoreria" type="checkbox" value="1"> Este departamento corresponde a Tesorería</label><label>Estatus<select name="estatus"><option>ACTIVO</option><option>INACTIVO</option></select></label><div class="form-actions full"><button type="button" class="btn btn-ghost" data-close-modal>Cancelar</button><button class="btn btn-primary" type="submit">Guardar departamento</button></div></form></div></div>
